package ktanesolver.module.modded.regular.mazematics;
import static org.assertj.core.api.Assertions.assertThat;import java.util.List;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class MazematicsSolverTest{@Test void findsAValidWrappedMazePathAndStoresSouvenirValues(){ModuleEntity m=new ModuleEntity();var input=new MazematicsInput(List.of(1,2,3,4,5,6,7,8),"A1",20,29);var result=(SolveSuccess<MazematicsOutput>)new MazematicsSolver().solve(new RoundEntity(),new BombEntity(),m,input);assertThat(result.output().moves()).containsExactly("up","left");assertThat(result.output().runningValues()).containsExactly(24,29);assertThat(result.output().restrictedValues()).isEqualTo("prime numbers");assertThat(result.output().twitchCommand()).isEqualTo("press display up left");assertThat(m.getState()).containsEntry("mazematicsInitialValue",20).containsEntry("mazematicsGoalValue",29);}}
